<?php
namespace App\Http\Controllers;
use App\Models\{Venue,Organization,Seat}; use Illuminate\Http\Request; use Illuminate\Support\Str;
class AdminVenueController extends Controller { public function index(){return view('admin.venues.index',['venues'=>Venue::withCount('seats')->latest()->paginate(15)]);} public function create(){return view('admin.venues.form',['venue'=>new Venue]);} public function store(Request $r){$d=$r->validate(['name'=>'required|max:190','city'=>'required|max:100','address'=>'nullable|max:500','rows'=>'required|integer|min:1|max:30','seats_per_row'=>'required|integer|min:1|max:50']);$org=Organization::firstOrCreate(['slug'=>'cinemaplus'],['name'=>'سینماپلاس']);$v=Venue::create(['organization_id'=>$org->id,'name'=>$d['name'],'city'=>$d['city'],'address'=>$d['address']??null,'capacity'=>$d['rows']*$d['seats_per_row']]);for($row=0;$row<$d['rows'];$row++)for($n=1;$n<=$d['seats_per_row'];$n++)Seat::create(['venue_id'=>$v->id,'row_label'=>chr(1575+$row),'number'=>$n,'type'=>$row===0?'vip':'standard']);return redirect()->route('admin.venues.index')->with('success','سالن ثبت شد.');} public function destroy(Venue $venue){$venue->delete();return back()->with('success','سالن حذف شد.');} }
